import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  progress_completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  available_at INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, seq);
CREATE TABLE IF NOT EXISTS heartbeats (
  name TEXT PRIMARY KEY,
  at_ms INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}
import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** Processing attempts allowed in total before a job is marked failed. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must be within 250 ms to 2 s. */
export const RETRY_DELAY_MS = 500;
/** Time each processing step takes. */
export const STEP_MS = 100;
/** The worker is "up" if its heartbeat is at most this old. */
export const HEARTBEAT_STALE_MS = 3_000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as stored in SQLite. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  /** Epoch milliseconds. A queued job is eligible for pickup once this has passed. */
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function nowIso(): string {
  return new Date().toISOString();
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.result_output === null ? null : { output: row.result_output },
    error: row.error,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Runs `fn` inside a write transaction. BEGIN IMMEDIATE takes the write lock up front, so read-then-write is atomic across processes. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function findJob(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | undefined;
}

export type SubmitOutcome =
  | { kind: 'created'; job: JobRow }
  | { kind: 'replayed'; job: JobRow }
  | { kind: 'conflict' };

/** Creates a job, or returns the job already created under the same idempotency key. */
export function submitJob(db: DatabaseSync, input: NewJob): SubmitOutcome {
  return transaction(db, (): SubmitOutcome => {
    if (input.idempotencyKey !== undefined) {
      const existing = db
        .prepare('SELECT * FROM jobs WHERE idempotency_key = ?')
        .get(input.idempotencyKey) as unknown as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === input.input && existing.steps === input.steps && existing.fail_attempts === input.failAttempts;
        return same ? { kind: 'replayed', job: existing } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                         result_output, error, idempotency_key, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, 0, ?, ?)`,
    ).run(id, input.input, input.steps, input.failAttempts, input.idempotencyKey ?? null, now, now);
    return { kind: 'created', job: findJob(db, id)! };
  });
}

/** Records the worker's liveness. */
export function writeHeartbeat(db: DatabaseSync, now: number = Date.now()): void {
  db.prepare(
    `INSERT INTO heartbeats (name, at_ms) VALUES ('worker', ?)
     ON CONFLICT(name) DO UPDATE SET at_ms = excluded.at_ms`,
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
}

export function isWorkerUp(db: DatabaseSync, now: number = Date.now()): boolean {
  const row = db.prepare("SELECT at_ms FROM heartbeats WHERE name = 'worker'").get() as { at_ms: number } | undefined;
  return row !== undefined && now - row.at_ms <= HEARTBEAT_STALE_MS;
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { findJob, isWorkerUp, listJobs, submitJob, toJob } from './jobs.ts';

const MAX_BODY_BYTES = 100 * 1024;
const MAX_INPUT_LENGTH = 1000;
const STEPS_RANGE = [1, 20] as const;
const FAIL_ATTEMPTS_RANGE = [0, 5] as const;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, headers);
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow });
}

function readBody(req: IncomingMessage): Promise<{ text: string } | { tooLarge: true }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!tooLarge) chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? { tooLarge: true } : { text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', reject);
  });
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isIntegerIn(v: unknown, [min, max]: readonly [number, number]): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

interface ValidJob {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | undefined;
}

/** Validates a submission. Returns the job with defaults applied, or the offending fields. */
function validateSubmission(req: IncomingMessage, rawBody: string): ValidJob | FieldError[] {
  const fields: FieldError[] = [];

  const contentType = Array.isArray(req.headers['content-type']) ? '' : (req.headers['content-type'] ?? '');
  const mediaType = contentType.split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    return [{ field: 'body', message: 'Content-Type must be application/json.' }];
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    return [{ field: 'body', message: 'Body must be valid JSON.' }];
  }
  if (!isPlainObject(parsed)) return [{ field: 'body', message: 'Body must be a JSON object.' }];

  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps = DEFAULT_STEPS, failAttempts = DEFAULT_FAIL_ATTEMPTS } = parsed;
  if (!('input' in parsed)) {
    fields.push({ field: 'input', message: 'Required.' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string.' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `Must be 1 to ${MAX_INPUT_LENGTH} characters.` });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }

  if ('steps' in parsed && !isIntegerIn(steps, STEPS_RANGE)) {
    fields.push({ field: 'steps', message: `Must be an integer from ${STEPS_RANGE[0]} to ${STEPS_RANGE[1]}.` });
  }
  if ('failAttempts' in parsed && !isIntegerIn(failAttempts, FAIL_ATTEMPTS_RANGE)) {
    fields.push({
      field: 'failAttempts',
      message: `Must be an integer from ${FAIL_ATTEMPTS_RANGE[0]} to ${FAIL_ATTEMPTS_RANGE[1]}.`,
    });
  }

  const rawKey = req.headers['idempotency-key'];
  // A repeated header arrives as an array; joining it makes the pattern check reject it.
  const key = Array.isArray(rawKey) ? rawKey.join(', ') : rawKey;
  if (key !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  if (fields.length > 0) return fields;
  return {
    input: input as string,
    steps: steps as number,
    failAttempts: failAttempts as number,
    idempotencyKey: key,
  };
}

async function handlePostJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  if ('tooLarge' in body) {
    return sendError(res, 400, 'invalid_request', 'Invalid job submission.', [
      { field: 'body', message: `Body must be at most ${MAX_BODY_BYTES} bytes.` },
    ]);
  }

  const valid = validateSubmission(req, body.text);
  if (Array.isArray(valid)) {
    return sendError(res, 400, 'invalid_request', 'Invalid job submission.', valid);
  }

  const outcome = submitJob(db, valid);
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.job));
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = findJob(db, id);
  if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
  sendJson(res, 200, toJob(row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db).map(toJob) });
    if (method === 'POST') return handlePostJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return handleGetJob(res, match[1]!);
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error(`request failed: ${e instanceof Error ? e.message : String(e)}`);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  // Force exit if a request is still in flight after a short grace period.
  setTimeout(() => {
    db.close();
    process.exit(0);
  }, 2_000).unref();
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  MAX_ATTEMPTS,
  RETRY_DELAY_MS,
  STEP_MS,
  clearHeartbeat,
  nowIso,
  transaction,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

const HEARTBEAT_MS = 1_000;
const POLL_MS = 200;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** A job left `running` by a worker that died is processed again from the start. */
function recoverInterruptedJobs(db: DatabaseSync): void {
  const result = db
    .prepare(
      "UPDATE jobs SET status = 'queued', available_at = 0, progress_completed = 0, updated_at = ? WHERE status = 'running'",
    )
    .run(nowIso());
  if (Number(result.changes) > 0) console.log(`requeued ${result.changes} interrupted job(s)`);
}

/** Moves the next eligible queued job (oldest first) to running and starts a new attempt. */
function claimNext(db: DatabaseSync): JobRow | undefined {
  return transaction(db, () => {
    const next = db
      .prepare("SELECT seq FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as { seq: number } | undefined;
    if (!next) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?",
    ).run(nowIso(), next.seq);
    return db.prepare('SELECT * FROM jobs WHERE seq = ?').get(next.seq) as unknown as JobRow;
  });
}

/** Puts an interrupted (shutdown-time) attempt back in the queue without counting it. */
function revertAttempt(db: DatabaseSync, job: JobRow): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', attempts = attempts - 1, progress_completed = 0, updated_at = ? WHERE seq = ? AND status = 'running'",
  ).run(nowIso(), job.seq);
}

async function processAttempt(db: DatabaseSync, job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: the attempt fails at its first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return revertAttempt(db, job);
    if (attempt >= MAX_ATTEMPTS) {
      db.prepare(
        "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, progress_completed = 0, updated_at = ? WHERE seq = ?",
      ).run(nowIso(), job.seq);
      console.log(`job ${job.id} failed after ${attempt} attempts`);
    } else {
      db.prepare("UPDATE jobs SET status = 'queued', available_at = ?, updated_at = ? WHERE seq = ?").run(
        Date.now() + RETRY_DELAY_MS,
        nowIso(),
        job.seq,
      );
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return revertAttempt(db, job);
    db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?').run(step, nowIso(), job.seq);
  }

  db.prepare(
    "UPDATE jobs SET status = 'completed', progress_completed = ?, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?",
  ).run(job.steps, job.input.toUpperCase(), nowIso(), job.seq);
  console.log(`job ${job.id} completed`);
}

function safely(label: string, fn: () => void): void {
  try {
    fn();
  } catch (e) {
    console.error(`${label} failed: ${e instanceof Error ? e.message : String(e)}`);
  }
}

recoverInterruptedJobs(db);
safely('heartbeat', () => writeHeartbeat(db));
const heartbeat = setInterval(() => safely('heartbeat', () => writeHeartbeat(db)), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNext(db);
    if (job) await processAttempt(db, job);
    else await sleep(POLL_MS);
  } catch (e) {
    console.error(`worker loop error: ${e instanceof Error ? e.message : String(e)}`);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeat);
safely('clear heartbeat', () => clearHeartbeat(db));
db.close();
console.log('worker stopped');
process.exit(0);
