<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Job tracker</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 48rem; padding: 0 1rem; color: #222; }
    form { display: grid; grid-template-columns: 1fr 6rem 9rem auto; gap: .5rem; align-items: end; }
    label { display: flex; flex-direction: column; font-size: .85rem; gap: .2rem; }
    input { font: inherit; padding: .35rem; }
    button { font: inherit; padding: .35rem .9rem; }
    [role="alert"] { color: #a00; margin: .75rem 0; white-space: pre-line; }
    [role="alert"]:empty { display: none; }
    ul { list-style: none; padding: 0; }
    li { border: 1px solid #ddd; border-radius: 4px; padding: .5rem .75rem; margin: .4rem 0; display: grid; grid-template-columns: 1fr auto auto; gap: .5rem; }
    .meta { grid-column: 1 / -1; font-size: .8rem; color: #666; }
    .status-completed { color: #1a7f37; }
    .status-failed { color: #a00; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" maxlength="1000" autocomplete="off" required>
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" placeholder="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" placeholder="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit</button>
  </form>

  <div data-testid="form-error" role="alert"></div>

  <ul data-testid="job-list"></ul>

  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const inputEl = document.querySelector('[data-testid="job-input"]');
    const stepsEl = document.querySelector('[data-testid="job-steps"]');
    const failEl = document.querySelector('[data-testid="job-fail-attempts"]');
    const submitBtn = document.querySelector('[data-testid="job-submit"]');
    const errorEl = document.querySelector('[data-testid="form-error"]');
    const listEl = document.querySelector('[data-testid="job-list"]');

    // Numeric-looking text is sent as a number so the API validates it; blank means "use the default".
    function numericOrRaw(text) {
      const trimmed = text.trim();
      if (trimmed === '') return undefined;
      const n = Number(trimmed);
      return Number.isFinite(n) ? n : text;
    }

    function describeRejection(status, data) {
      const err = data && data.error;
      if (!err) return `Request failed with status ${status}.`;
      const lines = [err.message || 'Request rejected.'];
      for (const f of err.fields || []) lines.push(`${f.field}: ${f.message}`);
      return lines.join('\n');
    }

    function element(tag, testid, text) {
      const el = document.createElement(tag);
      if (testid) el.setAttribute('data-testid', testid);
      if (text !== undefined) el.textContent = text;
      return el;
    }

    function resultText(job) {
      if (job.status === 'completed' && job.result) return job.result.output;
      if (job.status === 'failed') return job.error || '';
      return '';
    }

    function renderJob(job) {
      const li = element('li', 'job-item');
      li.setAttribute('data-job-id', job.id);

      const left = element('div');
      left.append(element('strong', null, job.input), element('div', null, `attempts: ${job.attempts}`));

      const status = element('span', 'job-status', job.status);
      status.classList.add(`status-${job.status}`);
      const progress = element('span', 'job-progress', `${job.progress.completed}/${job.progress.total}`);
      const result = element('span', 'job-result', resultText(job));

      li.append(left, status, progress, result);
      return li;
    }

    async function refresh() {
      try {
        const res = await fetch('/api/jobs', { cache: 'no-store' });
        if (!res.ok) return;
        const data = await res.json();
        listEl.replaceChildren(...data.jobs.map(renderJob));
      } catch {
        // Keep the last rendered list; the next poll will try again.
      }
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorEl.textContent = '';

      const body = { input: inputEl.value };
      const steps = numericOrRaw(stepsEl.value);
      const failAttempts = numericOrRaw(failEl.value);
      if (steps !== undefined) body.steps = steps;
      if (failAttempts !== undefined) body.failAttempts = failAttempts;

      submitBtn.disabled = true;
      try {
        const res = await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        const data = await res.json().catch(() => null);
        if (!res.ok) {
          errorEl.textContent = describeRejection(res.status, data);
          return;
        }
        inputEl.value = '';
        stepsEl.value = '';
        failEl.value = '';
        await refresh();
      } catch (err) {
        errorEl.textContent = `Could not reach the server: ${err.message}`;
      } finally {
        submitBtn.disabled = false;
      }
    });

    refresh();
    setInterval(refresh, 1000);
  </script>
</body>
</html>

